L79: const MAX_RECENT_LIMIT = 500;
L80: /** Clamp a panel-supplied `limit` into `[1, MAX_RECENT_LIMIT]`, defaulting when absent/invalid. */
L81: function resolveLimit(query, fallback) {
L82:     const value = readPositiveNumber(query?.limit) ?? fallback;
L83:     return Math.min(MAX_RECENT_LIMIT, Math.max(1, Math.trunc(value)));
