L85: /** Placeholder shown for a table cell whose source value is `null`/unmeasured. */
L86: const NO_VALUE = '—';
L87: /** Cap this many characters before an error message rides into a table cell (matches the DB column's practical display width). */
L88: const ERROR_MESSAGE_CAP = 500;
L89: /** Cap a run's error message to {@link ERROR_MESSAGE_CAP} characters. `resolve()` output bypasses
L90:  * Telescope's entry redaction pipeline (that only runs on Watcher-recorded entries) — this cap is a
L91:  * stopgap so an unbounded stack trace never rides straight into a table cell unbounded. */
L92: export function capErrorMessage(message) {
L93:     if (message === null)
L94:         return NO_VALUE;
L95:     return message.length > ERROR_MESSAGE_CAP ? `${message.slice(0, ERROR_MESSAGE_CAP)}…` : message;
L96: }
L97: /** Build a governance `DataProvider` from a fetch + a format step. Degrades to `format([])` when the
L98:  * read-model isn't bound — the empty-but-valid shape every formatter already yields for `[]`. */
L99: function governanceProvider(name, arg, fetch, format) {
L100:     return {
L101:         name,
L102:         async resolve(query, _ctx) {
L103:             const queries = getTelescopeGovernanceQueries();
L104:             const rows = queries ? await fetch(queries, arg(query)) : [];
L105:             return format(rows);
L106:         },
L107:     };
L108: }
L109: /** stat → authoritative total spend (USD) over the range. */
L110: export function agentSpendTotalProvider() {
L111:     return governanceProvider('agent.spend.totalCost', resolveRange, (queries, range) => queries.spendByModel(range), (rows) => ({
L112:         value: roundCents(rows.reduce((sum, row) => sum + row.costUsd, 0)),
L113:     }));
L114: }
L115: /** stat → authoritative total tokens (input + output) over the range. */
L116: export function agentTokensTotalProvider() {
L117:     return governanceProvider('agent.spend.totalTokens', resolveRange, (queries, range) => queries.spendByModel(range), (rows) => ({
L118:         value: rows.reduce((sum, row) => sum + row.inputTokens + row.outputTokens, 0),
L119:     }));
L120: }
L121: /** breakdown → spend share per model (models with zero cost dropped from the donut). */
L122: export function agentSpendByModelProvider() {
L123:     return governanceProvider('agent.spend.byModel', resolveRange, (queries, range) => queries.spendByModel(range), (rows) => ({
L124:         segments: rows
L125:             .filter((row) => row.costUsd > 0)
L126:             .map((row) => ({ label: row.modelId, value: roundCents(row.costUsd) })),
L127:     }));
L128: }
L129: /** table → per-model requests / in+out tokens / cost. */

