L5: /** API types this client understands (section 7). Others are skipped. */
L6: export const KNOWN_API_TYPES = ['openapi', 'mcp'];
L7: export function listApis(company) {
L8:     return (company.document.apis ?? []).filter((a) => a && KNOWN_API_TYPES.includes(a.type) && typeof a.url === 'string');
L9: }
L10: export function pickApi(company, type, index) {
L11:     const apis = listApis(company).filter((a) => a.type === type);
L12:     if (apis.length === 0)
L13:         throw new PoppyError('no_api', `Company lists no ${type} API`);
L14:     const api = apis[index ?? 0];
L15:     if (!api)
L16:         throw new PoppyError('no_api', `no ${type} API at index ${index}`);
L17:     requireSecureUrl(api.url, `${type} url`, company.security);
L18:     return api;
L19: }
L20: /** Loads an OpenAPI description. Tried as a public document first; through the Session if that's refused. */
L21: export async function loadOpenApi(company, api) {
L22:     const res = await company.http.request(api.url, { headers: { accept: 'application/json' } });
L23:     if (res.ok)
L24:         return (await readJson(res)) ?? {};
L25:     if (res.status === 401 || res.status === 403) {
L26:         const { body } = await company.json(api.url, {
L27:             headers: { accept: 'application/json' },
L28:             service: api.url,
L29:         });
L30:         return body ?? {};
L31:     }
L32:     throw new PoppyError(`http_${res.status}`, `could not load ${api.url}`);
L33: }
L34: /** The API's base URL: `servers[0].url` resolved against the description's URL. */
L35: export function apiBaseUrl(doc, api) {
L36:     const server = doc.servers?.[0]?.url;
L37:     return new URL(server ?? '/', api.url).toString().replace(/\/+$/, '');
L38: }
L39: /**
