L12: /**
L13:  * Step 2: reads the one-time code from the HTML of the page the agent's OWN browser loaded in step
L14:  * 1 (section 6). Pass it nothing else: a code from anywhere else may come from someone else's
L15:  * browser, which would then join the User's Session (10.6). Keep the code out of model context.
L16:  */
L17: export function browserJoinCode(html) {
L18:     for (const tag of html.match(/<input\b[^>]*>/gi) ?? []) {
L19:         if (!/\bname\s*=\s*["']?code["']?(?:\s|\/|>)/i.test(tag))
L20:             continue;
L21:         const value = /\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag);
L22:         const code = value?.[1] ?? value?.[2] ?? value?.[3];
L23:         if (code)
L24:             return code;
L25:     }
L26:     throw new PoppyError('invalid_browser_page', 'the browser-session page has no code field');
L27: }
L28: /**
L29:  * Step 2: authorizes the code with the Session header and, if signed in, the access token, which
L30:  * never reaches the browser. The agent's browser then submits the form (step 3); after a failure,
L31:  * start again at step 1.
L32:  */
L33: export async function authorizeBrowserJoin(company, code, opts = {}) {
L34:     const res = await company.fetch(`${browserSessionEndpoint(company).replace(/\/+$/, '')}/authorize`, {
L35:         method: 'POST',
L36:         headers: { 'content-type': 'application/json' },
L37:         body: JSON.stringify({ code }),
L38:         ...(opts.signedOut ? { signedOut: true } : {}),
L39:     });
L40:     if (res.status !== 204)
L41:         await throwForResponse(res);
L42: }
