        allowPositionals: true,
        strict: false,
        options: {
            help: { type: 'boolean', short: 'h' },
            state: { type: 'string' },
            profile: { type: 'string' },
            'insecure-dev': { type: 'boolean' },
            'base-url': { type: 'string' },
            name: { type: 'string' },
            'logo-uri': { type: 'string' },
            'rotate-keys': { type: 'boolean' },
            port: { type: 'string' },
            host: { type: 'string' },
            new: { type: 'boolean' },
            scope: { type: 'string' },
            resource: { type: 'string' },
            method: { type: 'string' },
            'no-open': { type: 'boolean' },
            data: { type: 'string' },
            api: { type: 'string' },
            conversation: { type: 'string' },
            as: { type: 'string' },
            'no-stream': { type: 'boolean' },
            page: { type: 'string' },
            model: { type: 'string' },
            'max-steps': { type: 'string' },
            yes: { type: 'boolean' },
        },
    });
