async function cmdStatus(ctx, domain) {
    const companies = ctx.store.profile(ctx.profile).companies;
    const id = ctx.store.data.identity;
    out(`identity: ${id ? `${id.baseUrl}/agent.json` : '(none: run init)'}   profile: ${ctx.profile}`);
    for (const s of Object.values(companies)) {
        if (domain && !s.domains.includes(domain.toLowerCase()))
            continue;
        const t = s.tokens.default;
        out(`${bold(s.issuer)}  (${s.domains.join(', ')})`);
        out(`  user_id ${s.userId}   session ${s.sessionId ?? '-'}   ${s.accountToken ? 'signed in' : 'signed out'}${t ? ` scope="${t.scope}" expires ${new Date(t.expiresAt).toISOString()}` : ''}`);
        out(`  refresh token: ${s.accountToken ? `yes (scope "${s.accountToken.scope}", via ${s.accountToken.via})` : 'no'}`);
        const convs = Object.entries(s.conversations).filter(([, c]) => !c.closed);
