    const r = await ask(c, task, {
        apiKey,
        model: str(ctx.values.model) ?? process.env.POPPY_AGENT_MODEL ?? DEFAULT_MODEL,
        maxSteps: ctx.values['max-steps'] ? Number(ctx.values['max-steps']) : 8,
        baseUrl: process.env.POPPY_AGENT_LLM_URL,
